const vm = require('node:vm');
const snippet = JSON.parse(process.argv[1]);
const style = { color: 'rgb(255, 255, 255)', backgroundColor: 'rgba(0, 0, 0, 0)' };
const result = vm.runInNewContext('(' + snippet.replace(/;\s*$/, '') + ')({})', {window: {getComputedStyle: () => style}}, {timeout: 1000});
process.stdout.write(JSON.stringify(result));
